    "title": "The Influence of Wheelchair Users on Movement in a Bottleneck and a Corridor",
    "venue": "Journal of Advanced Transportation",
    "year": 2019,
    "referenceCount": 106,
    "citationCount": 42,
    "openAccessPdf": {
